script:
(function () {
  'use strict';
  // Fixed-rate home equity loan: borrowing limit, payment, true cost and APR.
  //   Most you can borrow = home value * combined LTV limit - mortgage balance (never below 0).
  //   Closing costs: deducted from the money you receive, paid in cash, or added to the loan.
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = years * 12 (M = L / n at 0%).
  //   APR: the annual rate a at which the payments' present value equals the amount financed
  //   (loan minus closing costs; just the amount you asked for when costs are added to the loan),
  //   PV = M * (1 - (1 + a/12)^-n) / (a/12), solved by bisection.
  // Verified in Node (scratchpad tests/w3re): $150,000 at 8% for 15 yrs = $1,433.48/mo, total of
  //   payments $258,026.06, interest $108,026.06 (all match a published calculator's defaults and
  //   the closed form); $600,000 home, $250,000 balance, 80% limit -> $230,000 maximum (same
  //   calculator); APR with no costs equals the note rate; APR with $7,500 of costs on that loan is
  //   8.860%, matching an independent Newton's-method solve; costs added to the loan raise the
  //   payment by the amortized cost; 0% rate -> L / n; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(loan, annualRate, months) {
    if (loan <= 0 || months <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return loan / months;
    return loan * i / (1 - Math.pow(1 + i, -months));
  }

  function presentValue(pay, annualRate, months) {
    var i = annualRate / 12;
    if (i === 0) return pay * months;
    return pay * (1 - Math.pow(1 + i, -months)) / i;
  }

  // Annual rate (decimal) at which the payments are worth exactly `financed` today.
  function apr(pay, financed, months) {
    if (!(financed > 0) || !(pay > 0)) return NaN;
    if (presentValue(pay, 0, months) <= financed) return 0;
    var lo = 0, hi = 1;
    while (presentValue(pay, hi, months) > financed && hi < 100) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (presentValue(pay, mid, months) > financed) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function schedule(loan, annualRate, months) {
    var pay = payment(loan, annualRate, months), bal = loan, rows = [], p = 0, intr = 0, total = 0;
    for (var m = 1; m <= months; m++) {
      var interest = bal * annualRate / 12;
      var principal = m === months ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      p += principal; intr += interest; total += interest;
      if (m % 12 === 0 || m === months) {
        rows.push({ year: Math.ceil(m / 12), principal: p, interest: intr, balance: bal });
        p = 0; intr = 0;
      }
    }
    return { pay: pay, rows: rows, totalInterest: total };
  }

  function clearResults() {
    ['hlMonthly', 'hlMax', 'hlCash', 'hlApr', 'hlLoanOut', 'hlCostsOut', 'hlTotalInterest', 'hlTotalPaid', 'hlCltvOut',
     'hlEquityLeft'].forEach(function (id) { setText(id, '–'); });
    el('hlWarn').hidden = true;
    el('hlSchedule').innerHTML = '';
  }

  function update() {
    var value = read('hlValue'), balance = read('hlBalance', true), cltv = parseFloat(el('hlCltv').value),
        amount = read('hlAmount'), rate = read('hlRate'), years = read('hlTerm'),
        costs = read('hlCosts', true), costsUnit = el('hlCostsUnit').value, how = el('hlCostsPaid').value;
    var msg = '';
    if (isNaN(value) || value <= 0) msg = 'Enter your home’s current value, greater than $0.';
    else if (isNaN(balance) || balance < 0) msg = 'The mortgage balance cannot be negative.';
    else if (isNaN(amount) || amount <= 0) msg = 'Enter the amount you want to borrow, greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(years) || years < 1 || years > 30 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 30 whole years.';
    else if (isNaN(costs) || costs < 0) msg = 'Closing costs cannot be negative.';
    else if (costsUnit === 'percent' && costs > 10) msg = 'Enter closing costs of 10% of the loan or less.';
    var costAmt = costsUnit === 'percent' ? amount * costs / 100 : costs;
    if (!msg && how === 'deducted' && costAmt >= amount) msg = 'Closing costs deducted from the loan must be less than the amount you borrow.';
    var error = el('hlError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var maxBorrow = Math.max(0, value * cltv / 100 - balance);
    var loan = how === 'financed' ? amount + costAmt : amount;
    var months = years * 12;
    var r = schedule(loan, rate / 100, months);
    var cash = how === 'deducted' ? amount - costAmt : amount;
    var financedAmt = how === 'financed' ? amount : amount - costAmt;
    var a = apr(r.pay, financedAmt, months);
    var newCltv = (balance + loan) / value * 100;

    setText('hlMonthly', money.format(r.pay));
    setText('hlMax', money0.format(maxBorrow));
    setText('hlCash', money.format(cash));
    setText('hlApr', isFinite(a) ? (a * 100).toFixed(3) + '%' : '–');
    setText('hlLoanOut', money.format(loan));
    setText('hlCostsOut', money.format(costAmt) + (how === 'deducted' ? ' (taken from the loan)' : how === 'upfront' ? ' (paid in cash)' : ' (added to the loan)'));
    setText('hlTotalInterest', money.format(r.totalInterest));
    setText('hlTotalPaid', money.format(loan + r.totalInterest));
    setText('hlCltvOut', newCltv.toFixed(1) + '%');
    setText('hlEquityLeft', money0.format(value - balance - loan));

    var warn = el('hlWarn');
    if (loan > maxBorrow + 0.005) {
      warn.hidden = false;
      setText('hlWarnText', maxBorrow > 0
        ? 'This loan is ' + money0.format(loan - maxBorrow) + ' more than lenders usually allow with a combined limit of ' + cltv + '%. Borrow ' + money0.format(maxBorrow) + ' or less, or look for a lender with a higher limit.'
        : 'Your mortgage already uses the whole combined limit of ' + cltv + '%, so lenders using that limit would not offer a home equity loan.');
    } else {
      warn.hidden = true;
    }

    el('hlSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.principal) + '</td><td>' + money.format(row.interest) +
        '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('hlForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
